-- Dataset TokoMaju: tabel sumber pelanggan (sistem kasir/OLTP)
-- Kompatibel dengan MySQL/MariaDB dan PostgreSQL.
-- Jalankan di database sumber, misalnya: CREATE DATABASE tokomaju_oltp;

DROP TABLE IF EXISTS pelanggan;
CREATE TABLE pelanggan (
  id_pelanggan VARCHAR(10) PRIMARY KEY,
  nama VARCHAR(100) NOT NULL,
  jenis_kelamin VARCHAR(20),
  kota VARCHAR(50),
  provinsi VARCHAR(50),
  telepon VARCHAR(25),
  email VARCHAR(100),
  tgl_daftar DATE
);

